CREATE TEMP TABLE jb_alias(old_name text,new_name text) ON COMMIT DROP;
INSERT INTO jb_alias VALUES
('SANITÁRIO DEFICIENTES','SANITÁRIO ACESSÍVEL'),('DIRETORIA DE GESTÃO/CTIC - COORDENAÇÃO DA TECNOLOGIA DA INFORMAÇÃO','DIRETORIA DE GESTÃO/CTIC - COORDENAÇÃO DE TECNOLOGIA DA INFORMAÇÃO'),('ALOJAMENTO LIMPEZA','ALOJAMENTO DA LIMPEZA'),('SALA DE REUNIÇÃO','SALA DE REUNIÃO'),('MUSEU JARDIM BOTÂNICO','MUSEU DO JARDIM BOTÂNICO'),('MIRANTE DA IMPRESSA','MIRANTE DA IMPRENSA'),('BANHEIRO DO RECANTO DA MATA FEMININO','BANHEIRO FEMININO DO RECANTO DA MATA'),('BANHEIRO DO RECANTO DA MATA MASCULINO','BANHEIRO MASCULINO DO RECANTO DA MATA'),('PONTE BROMELIÁRIO','PONTE DO BROMELIÁRIO'),('SALA 312 - ALMOXARIFADO LABORATÓRIO DE SEMENTES','SALA 312 - ALMOXARIFADO DO LABORATÓRIO DE SEMENTES'),('SALA DE SECAGEM DE SEMENTE','SALA DE SECAGEM DE SEMENTES'),('SALA DESTILADOR','SALA DO DESTILADOR'),('ACESSO TELHADO/ALMOXARIFADO LIMPEZA','ACESSO AO TELHADO / ALMOXARIFADO DA LIMPEZA'),('ALMOXARIFADO LABORATÓRIO DE SEMENTES','ALMOXARIFADO DO LABORATÓRIO DE SEMENTES'),('SALA 102 SALA DE MULTIUSO','SALA 102 - SALA DE MULTIUSO');
DO $$
DECLARE
 data jsonb; loc jsonb; pav jsonb; secs jsonb; src record; sector text; candidate text; normalized text; idx integer; li integer; pi integer; si integer; lc integer:=0; pc integer:=0; sc integer:=0; renamed integer:=0; alias_name text;
BEGIN
 SELECT locais INTO STRICT data FROM public.clientes WHERE id='bb8b067b-1a2d-4e11-826e-63a1d65d2784' FOR UPDATE;
 FOR src IN SELECT * FROM jb_import LOOP
  SELECT ord::integer-1 INTO li FROM jsonb_array_elements(data) WITH ORDINALITY t(v,ord) WHERE regexp_replace(translate(upper(v->>'descricao'),'ÁÀÂÃÉÊÍÓÔÕÚÜÇ','AAAAEEIOOOUUC'),'[^A-Z0-9]','','g')=regexp_replace(translate(upper(src.local),'ÁÀÂÃÉÊÍÓÔÕÚÜÇ','AAAAEEIOOOUUC'),'[^A-Z0-9]','','g');
  IF li IS NULL THEN
   loc=jsonb_build_object('id',gen_random_uuid(),'descricao',src.local,'pavimentos','[]'::jsonb);
   FOREACH candidate IN ARRAY ARRAY['cep','bairro','logradouro','numero','complemento','uf','cidade','latitude','longitude','areaTotal','areaConstruida','contato','telContato','relLinha1','relLinha2','relLinha3','relLinha4'] LOOP loc=loc||jsonb_build_object(candidate,''); END LOOP;
   data=data||jsonb_build_array(loc);li=jsonb_array_length(data)-1;lc=lc+1;
  END IF;
  loc=data->li;loc=jsonb_set(loc,'{descricao}',to_jsonb(src.local));
  SELECT ord::integer-1 INTO pi FROM jsonb_array_elements(loc->'pavimentos') WITH ORDINALITY t(v,ord) WHERE v->>'descricao'=src.pavimento OR replace(v->>'descricao','° PAVIMENTO','º ANDAR')=src.pavimento;
  IF pi IS NULL THEN loc=jsonb_set(loc,'{pavimentos}',(loc->'pavimentos')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'descricao',src.pavimento,'ativo',true,'setores','[]'::jsonb)));pi=jsonb_array_length(loc->'pavimentos')-1;pc=pc+1;END IF;
  pav=loc->'pavimentos'->pi;pav=jsonb_set(pav,'{descricao}',to_jsonb(src.pavimento));secs=coalesce(pav->'setores','[]'::jsonb);
  FOREACH sector IN ARRAY string_to_array(src.setores,'|') LOOP
   normalized=regexp_replace(translate(upper(sector),'ÁÀÂÃÉÊÍÓÔÕÚÜÇ','AAAAEEIOOOUUC'),'[^A-Z0-9]','','g');si=NULL;
   FOR idx IN 0..jsonb_array_length(secs)-1 LOOP
    candidate=secs->idx->>'descricao';SELECT new_name INTO alias_name FROM jb_alias WHERE old_name=candidate;
    candidate=coalesce(alias_name,candidate);
    IF regexp_replace(translate(upper(candidate),'ÁÀÂÃÉÊÍÓÔÕÚÜÇ','AAAAEEIOOOUUC'),'[^A-Z0-9]','','g')=normalized THEN si=idx;EXIT;END IF;
   END LOOP;
   IF si IS NULL THEN secs=secs||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'descricao',sector,'ativo',true));sc=sc+1;
   ELSE IF secs->si->>'descricao' IS DISTINCT FROM sector THEN renamed=renamed+1;secs=jsonb_set(secs,ARRAY[si::text,'descricao'],to_jsonb(sector));END IF;END IF;
  END LOOP;
  pav=jsonb_set(pav,'{setores}',secs);loc=jsonb_set(loc,ARRAY['pavimentos',pi::text],pav);data=jsonb_set(data,ARRAY[li::text],loc);
 END LOOP;
 IF jsonb_array_length(data)<>19 THEN RAISE EXCEPTION 'Quantidade inesperada de locais'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(data) l CROSS JOIN LATERAL jsonb_array_elements(l->'pavimentos') p)<>26 THEN RAISE EXCEPTION 'Quantidade inesperada de pavimentos'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(data) l CROSS JOIN LATERAL jsonb_array_elements(l->'pavimentos') p CROSS JOIN LATERAL jsonb_array_elements(p->'setores') s)<>246 THEN RAISE EXCEPTION 'Quantidade inesperada de setores'; END IF;
 UPDATE public.clientes SET locais=data WHERE id='bb8b067b-1a2d-4e11-826e-63a1d65d2784';
 RAISE NOTICE 'Novos locais %, pavimentos %, setores %, grafias revisadas %',lc,pc,sc,renamed;
END $$;